"""
Batch adaptive filtering with cycle-spun wavelet shrinkage and
residual-supported weak-extrema cancellation.

The returned sample at output i estimates input i + window_size - 1.
"""
import numpy as np


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.convolve(x, np.ones(window_size, dtype=float) / window_size, mode="valid")


def _robust_scale(values):
    values = np.asarray(values, dtype=float).reshape(-1)
    if values.size == 0:
        return 0.0
    med = np.median(values)
    return float(1.4826 * np.median(np.abs(values - med)))


def _fallback_smoother(x, window_size):
    """Centered local polynomial fallback, or a centered boxcar if unavailable."""
    x = np.asarray(x, dtype=float)
    n = len(x)
    if n < 3:
        return x.copy()
    k = min(max(5, 2 * (window_size // 2) + 1), n if n % 2 else n - 1)
    if k < 3:
        return x.copy()
    try:
        from scipy.signal import savgol_filter
        return np.asarray(savgol_filter(x, k, min(2, k - 1), mode="interp"), dtype=float)
    except Exception:
        padded = np.pad(x, (k // 2, k // 2), mode="edge")
        return np.convolve(padded, np.ones(k) / k, mode="valid")[:n]


def _filled_signs(y):
    d = np.diff(y)
    s = np.sign(d).astype(float)
    if s.size == 0:
        return s
    for i in range(1, len(s)):
        if s[i] == 0:
            s[i] = s[i - 1]
    for i in range(len(s) - 2, -1, -1):
        if s[i] == 0:
            s[i] = s[i + 1]
    return s


def _has_large_jump(x, left, right, jump_size):
    if right <= left:
        return False
    return bool(np.any(np.abs(np.diff(x[left:right + 1])) >= jump_size))


def _cancel_weak_excursions(y, reference, sigma):
    """
    Remove only extrema unsupported by a comparably sized raw excursion.
    Interpolation between enclosing extrema retains endpoint levels and avoids
    adding phase displacement.
    """
    y = np.asarray(y, dtype=float).copy()
    reference = np.asarray(reference, dtype=float)
    if len(y) < 7:
        return y

    residual = _robust_scale(reference - y)
    slope_scale = _robust_scale(np.diff(y))
    tau = max(0.35 * residual, 0.08 * slope_scale, 1e-12)
    jump_size = max(5.0 * sigma, 6.0 * tau, 1e-12)

    for _ in range(2):
        s = _filled_signs(y)
        extrema = np.flatnonzero(s[1:] != s[:-1]) + 1
        if extrema.size < 3:
            break

        changed = False
        # Work from left to right; a changed interval is not reconsidered
        # until the next bounded pass.
        for j in range(1, len(extrema) - 1):
            left, center, right = map(int, extrema[j - 1:j + 2])
            if right - left < 2:
                continue

            left_prom = abs(y[center] - y[left])
            right_prom = abs(y[right] - y[center])
            weak = min(left_prom, right_prom) < 1.25 * tau
            if not weak:
                continue

            raw_left = abs(reference[center] - reference[left])
            raw_right = abs(reference[right] - reference[center])
            raw_unsupported = min(raw_left, raw_right) < 2.0 * tau
            if not raw_unsupported:
                continue
            if _has_large_jump(reference, left, right, jump_size):
                continue

            y[left:right + 1] = np.linspace(
                y[left], y[right], right - left + 1
            )
            changed = True
        if not changed:
            break
    return y


def _fused_curvature_reconstruction(x, sigma):
    """Fit robust cubic-like smooth trends independently inside detected regimes."""
    x = np.asarray(x, dtype=float).reshape(-1)
    n = x.size
    if n < 3:
        return x.copy()

    try:
        from scipy.linalg import solve_banded

        robust = max(float(sigma), 1e-8)
        spread = float(np.percentile(x, 75) - np.percentile(x, 25))
        jump = max(5.0 * robust, 0.18 * spread, 1e-8)

        # Only persistent level changes create regime boundaries.
        cuts = []
        for j in np.flatnonzero(np.abs(np.diff(x)) >= jump) + 1:
            left = x[max(0, j - 4):j]
            right = x[j:min(n, j + 4)]
            if left.size and right.size:
                if abs(np.median(right) - np.median(left)) >= jump:
                    cuts.append(int(j))
        bounds = [0] + cuts + [n]
        result = np.empty_like(x)

        def fit_segment(v):
            m = len(v)
            if m < 4:
                return v.copy()
            best = None
            best_cost = np.inf
            for multiplier in (0.25, 0.6, 1.2, 2.4):
                lam = multiplier * robust * robust * m
                y = v.copy()
                for _ in range(3):
                    r = v - y
                    scale = max(_robust_scale(r), robust * 0.25)
                    weights = np.minimum(1.0, 1.5 * scale / (np.abs(r) + 1e-12))
                    main = weights + lam * np.r_[
                        [1.0, 5.0], np.full(max(0, m - 4), 6.0), [5.0, 1.0]
                    ][:m]
                    upper = lam * np.r_[
                        [-2.0], np.full(max(0, m - 3), -4.0), [-2.0]
                    ][:m - 1]
                    second = lam * np.ones(max(0, m - 2))
                    ab = np.zeros((5, m), dtype=float)
                    ab[2] = main
                    ab[1, 1:] = upper
                    ab[3, :-1] = upper
                    ab[0, 2:] = second
                    ab[4, :-2] = second
                    y = solve_banded((2, 2), ab, weights * v)
                reversals = np.count_nonzero(
                    np.diff(np.sign(np.diff(y))) != 0
                )
                cost = np.median(np.abs(v - y)) / robust + 0.035 * reversals
                if np.isfinite(cost) and cost < best_cost:
                    best_cost, best = cost, y.copy()
            return best if best is not None else v.copy()

        for left, right in zip(bounds[:-1], bounds[1:]):
            result[left:right] = fit_segment(x[left:right])
        return result if np.all(np.isfinite(result)) else x.copy()
    except Exception:
        return x.copy()


def _bidirectional_ar_consensus(x, sigma):
    """Apply two-pass forward/backward ridge AR(8) consensus with overlap-add blocks."""
    x = np.asarray(x, dtype=float).reshape(-1)
    n = x.size
    if n < 12:
        return x.copy()

    order = 8
    block = 48
    hop = 16
    ridge = max(0.15 * float(sigma) ** 2, 1e-10)
    base_sigma = max(float(sigma), 1e-8)

    def stable_ar_fit(v):
        """Fit a centered, ridge-regularized AR(8) model with stability limiting."""
        v = np.asarray(v, dtype=float)
        if v.size <= order + 1:
            return np.zeros(order, dtype=float), float(np.median(v))
        center = float(np.median(v))
        z = v - center
        rows = []
        target = []
        for i in range(order, len(z)):
            rows.append(z[i - order:i][::-1])
            target.append(z[i])
        design = np.asarray(rows, dtype=float)
        target = np.asarray(target, dtype=float)
        gram = design.T @ design
        gram.flat[::order + 1] += ridge
        try:
            coef = np.linalg.solve(gram, design.T @ target)
        except np.linalg.LinAlgError:
            coef = np.linalg.lstsq(gram, design.T @ target, rcond=None)[0]
        norm = float(np.sum(np.abs(coef)))
        if norm > 0.98:
            coef *= 0.98 / norm
        return coef, center

    def predicted_series(v):
        """Generate local overlap-add AR predictions for one signal direction."""
        v = np.asarray(v, dtype=float)
        estimate = np.zeros(len(v), dtype=float)
        weights = np.zeros(len(v), dtype=float)
        starts = list(range(0, max(1, len(v) - order), hop))
        if starts[-1] != max(0, len(v) - block):
            starts.append(max(0, len(v) - block))

        for start in starts:
            stop = min(len(v), start + block)
            segment = v[start:stop]
            coef, center = stable_ar_fit(segment)
            length = stop - start
            pred = segment.copy()
            history = list(segment[:order])
            for k in range(order, length):
                state = np.asarray(history[-order:][::-1], dtype=float) - center
                pred[k] = center + float(np.dot(coef, state))
                history.append(pred[k])

            taper = np.hanning(length) if length > 2 else np.ones(length)
            taper = np.maximum(taper, 0.08)
            estimate[start:stop] += taper * pred
            weights[start:stop] += taper

        return estimate / np.maximum(weights, 1e-12)

    def consensus(observed):
        """Fuse raw samples with forward and backward AR predictions."""
        forward = predicted_series(observed)
        backward = predicted_series(observed[::-1])[::-1]
        innovation = np.minimum(
            np.abs(observed - forward), np.abs(observed - backward)
        )
        raw_weight = np.minimum(
            1.0, 2.5 * base_sigma / (innovation + 1e-12)
        )
        prediction_weight = 0.5 * (1.0 - raw_weight)
        return (
            raw_weight * observed
            + prediction_weight * forward
            + prediction_weight * backward
        )

    result = np.asarray(x, dtype=float).copy()
    for _ in range(2):
        result = consensus(result)

    deadband = 0.05 * base_sigma
    delta = result - x
    result = x + np.sign(delta) * np.maximum(np.abs(delta) - deadband, 0.0)
    return result if np.all(np.isfinite(result)) else x.copy()


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )

    if not np.all(np.isfinite(x)):
        finite = x[np.isfinite(x)]
        fill = float(np.median(finite)) if finite.size else 0.0
        x = np.nan_to_num(x, nan=fill, posinf=fill, neginf=fill)

    n = len(x)
    if n < 7:
        return _fallback_smoother(x, window_size)[window_size - 1:]

    smooth = None
    sigma = np.nan

    try:
        import pywt

        wavelet = pywt.Wavelet("db4")
        level = min(5, pywt.dwt_max_level(n, wavelet.dec_len))
        if level > 0:
            decompositions = []
            sigma_samples = []
            for shift in (0, 2, 4, 6):
                coeffs = pywt.wavedec(
                    np.roll(x, shift), wavelet, mode="symmetric", level=level
                )
                decompositions.append((shift, coeffs))
                finest = np.asarray(coeffs[-1], dtype=float)
                local = _robust_scale(finest) / 0.6745
                if np.isfinite(local) and local > 1e-12:
                    sigma_samples.append(local)

            sigma = (
                float(np.median(sigma_samples))
                if sigma_samples
                else _robust_scale(np.diff(x)) / np.sqrt(2.0)
            )
            sigma = max(float(sigma), 1e-12)
            threshold = sigma * np.sqrt(2.0 * np.log(max(n, 2)))

            reconstructions = []
            for shift, coeffs in decompositions:
                out = [np.asarray(coeffs[0], dtype=float).copy()]
                detail_count = len(coeffs) - 1
                for band, detail in enumerate(coeffs[1:]):
                    from_finest = detail_count - 1 - band
                    if from_finest <= 1:
                        factor = 1.0
                    elif from_finest == 2:
                        factor = 0.60
                    elif from_finest == 3:
                        factor = 0.30
                    else:
                        factor = 0.0
                    out.append(
                        pywt.threshold(
                            np.asarray(detail, dtype=float),
                            factor * threshold,
                            mode="soft",
                        )
                    )
                restored = pywt.waverec(out, wavelet, mode="symmetric")
                reconstructions.append(np.roll(np.asarray(restored[:n]), -shift))
            smooth = np.mean(np.stack(reconstructions), axis=0)
    except Exception:
        smooth = None

    if not np.isfinite(sigma) or sigma <= 1e-12:
        sigma = max(_robust_scale(np.diff(x)) / np.sqrt(2.0), 1e-12)

    if smooth is None or smooth.shape != x.shape or not np.all(np.isfinite(smooth)):
        smooth = _fallback_smoother(x, window_size)

    # Preserve isolated, persistent step changes against wavelet ringing.
    spread = float(np.percentile(x, 75) - np.percentile(x, 25))
    jump_threshold = max(5.0 * sigma, 0.18 * spread, 1e-12)
    jumps = np.flatnonzero(np.abs(np.diff(x)) >= jump_threshold) + 1
    for jump in jumps:
        left = x[max(0, jump - 4):jump]
        right = x[jump:min(n, jump + 4)]
        if left.size and right.size:
            lmed, rmed = np.median(left), np.median(right)
            if abs(rmed - lmed) >= jump_threshold:
                lo, hi = max(0, jump - 2), min(n, jump + 2)
                split = min(2, hi - lo)
                smooth[lo:hi] = np.r_[
                    np.full(split, lmed),
                    np.full(hi - lo - split, rmed),
                ]

    # Use bidirectional local AR consensus on the normal return path.
    # Forward and reverse predictions reduce phase delay while overlap-add
    # fitting adapts to changing local oscillation and trend structure.
    smooth = _bidirectional_ar_consensus(x, sigma)
    smooth = _cancel_weak_excursions(smooth, x, sigma)
    return np.asarray(smooth, dtype=float)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    np.random.seed(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(np.random.randn(length) * 0.05)
    noisy_signal = clean_signal + np.random.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is not None:
        delay = window_size - 1
        aligned_clean = clean_signal[delay:]
        aligned_noisy = noisy_signal[delay:]
        m = min(len(filtered_signal), len(aligned_clean))
        filtered_signal = filtered_signal[:m]
        aligned_clean = aligned_clean[:m]
        aligned_noisy = aligned_noisy[:m]
        correlation = (
            float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
            if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
            else 0.0
        )
        noise_before = np.var(aligned_noisy - aligned_clean)
        noise_after = np.var(filtered_signal - aligned_clean)
        noise_reduction = (
            float((noise_before - noise_after) / noise_before)
            if noise_before > 0 else 0.0
        )
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": aligned_clean,
            "noisy_signal": aligned_noisy,
            "correlation": correlation,
            "noise_reduction": noise_reduction,
            "signal_length": m,
        }

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": None,
        "noisy_signal": None,
        "correlation": 0,
        "noise_reduction": 0,
        "signal_length": len(filtered_signal),
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
